function getElementValue(elementName, iControl) {
    liveSelect = document.getElementById(elementName + iControl);
    try {
        if (liveSelect === null) {
            varValue = 0;
            return varValue;
        }
        varValue = liveSelect.value;
        if (varValue === undefined) {
            varValue = liveSelect.options[liveSelect.selectedIndex].text;
        } else {}
        return varValue
    } catch (err) {
        err.message;
        err.stack
    }
}

